---
import Layout from '../layouts/Layout.astro';
import {
  readContact,
  successMessage,
  validateContact,
  type ContactErrors,
  type ContactValues,
} from '../lib/contact';

export const prerender = false;

let values: ContactValues = { name: '', email: '', message: '' };
let errors: ContactErrors = {};
let success = '';

if (Astro.request.method === 'POST') {
  try {
    values = readContact(await Astro.request.formData());
  } catch {
    // An unreadable body is treated as an empty form.
  }
  errors = validateContact(values);
  if (Object.keys(errors).length === 0) {
    success = successMessage(values.name);
    values = { name: '', email: '', message: '' };
  } else {
    Astro.response.status = 400;
  }
}
---

<Layout title="Contact | Bookshelf">
  <h1>Contact</h1>
  <p class="success" role="status" hidden={!success}>{success}</p>
  <form method="post" action="/contact" novalidate>
    <div class="field">
      <label for="name">Name</label>
      <input
        id="name"
        name="name"
        type="text"
        autocomplete="name"
        value={values.name}
        aria-describedby="name-error"
        aria-invalid={errors.name ? 'true' : undefined}
      />
      <p class="error" id="name-error" data-error-for="name">{errors.name}</p>
    </div>
    <div class="field">
      <label for="email">Email</label>
      <input
        id="email"
        name="email"
        type="email"
        autocomplete="email"
        value={values.email}
        aria-describedby="email-error"
        aria-invalid={errors.email ? 'true' : undefined}
      />
      <p class="error" id="email-error" data-error-for="email">{errors.email}</p>
    </div>
    <div class="field">
      <label for="message">Message</label>
      <textarea
        id="message"
        name="message"
        rows="6"
        aria-describedby="message-error"
        aria-invalid={errors.message ? 'true' : undefined}>{values.message}</textarea>
      <p class="error" id="message-error" data-error-for="message">{errors.message}</p>
    </div>
    <button type="submit">Send</button>
  </form>
</Layout>

<script>
  import { readContact, validateContact, type ContactErrors } from '../lib/contact';

  const form = document.querySelector<HTMLFormElement>('form[action="/contact"]');
  const success = document.querySelector<HTMLParagraphElement>('.success');

  function showErrors(errors: ContactErrors) {
    for (const field of ['name', 'email', 'message'] as const) {
      const message = errors[field] ?? '';
      const output = document.querySelector(`[data-error-for="${field}"]`);
      const input = form?.elements.namedItem(field);
      if (output) output.textContent = message;
      if (input instanceof HTMLElement) {
        if (message) input.setAttribute('aria-invalid', 'true');
        else input.removeAttribute('aria-invalid');
      }
    }
  }

  function showSuccess(message: string) {
    if (!success) return;
    success.textContent = message;
    success.hidden = !message;
  }

  form?.addEventListener('submit', async (event) => {
    event.preventDefault();
    const data = new FormData(form);
    const errors = validateContact(readContact(data));
    showErrors(errors);
    showSuccess('');
    if (Object.keys(errors).length > 0) return;

    const submit = form.querySelector<HTMLButtonElement>('button[type="submit"]');
    if (submit) submit.disabled = true;
    try {
      const response = await fetch('/api/contact', { method: 'POST', body: data });
      const result: { ok: boolean; message?: string; errors?: ContactErrors } = await response.json();
      if (result.ok) {
        form.reset();
        showSuccess(result.message ?? '');
      } else {
        showErrors(result.errors ?? {});
      }
    } catch {
      // Fall back to a regular submission if the request could not be made.
      form.submit();
    } finally {
      if (submit) submit.disabled = false;
    }
  });
</script>

<style>
  form {
    display: grid;
    gap: 1rem;
    max-width: 32rem;
  }
  .field {
    display: grid;
    gap: 0.25rem;
  }
  .error {
    margin: 0;
    color: #c00;
  }
  .error:empty {
    display: none;
  }
  .success {
    padding: 0.5rem 0.75rem;
    border: 1px solid #0a0;
    border-radius: 0.25rem;
  }
  button[type='submit'] {
    justify-self: start;
  }
</style>
EOF
