import { defineMiddleware } from 'astro:middleware';

const SAFE_METHODS = new Set(['GET', 'HEAD', 'OPTIONS']);

// Rejects cross-site form submissions, like Astro's built-in `checkOrigin`,
// but also accepts the site's public origin given in the `ORIGIN` variable.
export const onRequest = defineMiddleware((context, next) => {
  const { request, url, isPrerendered } = context;
  if (isPrerendered || SAFE_METHODS.has(request.method)) return next();

  const site = process.env.ORIGIN?.replace(/\/+$/, '');
  const fetchSite = request.headers.get('sec-fetch-site');
  const origin = request.headers.get('origin');
  const allowed =
    fetchSite === 'same-origin' ||
    fetchSite === 'none' ||
    (!fetchSite && (!origin || origin === url.origin || origin === site)) ||
    (fetchSite === 'same-site' && origin !== null && (origin === url.origin || origin === site));

  if (!allowed) {
    return new Response(`Cross-site ${request.method} form submissions are forbidden`, { status: 403 });
  }
  return next();
});
EOF
